"""
    If there happened to be progress between the two statuses we check if it was valid.
    Thus, we return False if there was invalid progress, and True otherwise. (even if there was no progress)
    stage change counts as progress, but has to be done in the right order.
    also if both runs are in the same stage, we compare progress.

    :param status_old: json describing a run status as returned from the '/projects/{project_id}/runs/{run_id}/status'
                       endpoint
    :param status_new: same as above
    :return: False if the progress was not valid
    """
def has_progressed_validly(status_old: Any, status_new: Any) -> object {
    old_stage = status_old['current_stage']['number'];
    new_stage = status_new['current_stage']['number'];
    if (old_stage < new_stage) {
        return True;
    } elif (old_stage > new_stage) {
        return False;
    }
    if (
        ('progress' in status_old['current_stage'])
        and ('progress' in status_new['current_stage'])
    ) {
        assert (0 <= status_new['current_stage']['progress']['relative'] <= 1.0) , "{} not between 0 and 1".format(
            status_new['current_stage']['progress']['relative']
        );
        assert (0 <= status_old['current_stage']['progress']['relative'] <= 1.0) , "{} not between 0 and 1".format(
            status_old['current_stage']['progress']['relative']
        );
        if (
            status_new['current_stage']['progress']['relative']
            < status_old['current_stage']['progress']['relative']
        ) {
            return False;
        } else {
            return True;
        }
    } else {
        return True;
    }
}

"""Given two mean squared errors, corresponding to the prediction of
    a target column before and after data augmentation, computes
    their relative decrease
    """
def compute_mse_decrease(mse_before: Any, mse_after: Any) -> object {
    return ((mse_after - mse_before) / mse_before);
}

"""
	The mathematical formula to calculate the number of permutations is n^r where n is the number of options
	in this case we have (0-9) giving us 10 options.  And r = the permutations, the count of unknown numbers
	"""
def generateReplNumsList(count_of_unknown_numbers: Any) -> object {
    unkNums = count_of_unknown_numbers;
    count = 10 ** unkNums;
    my_list = `list();
    i = 0;
    for i in range(count) {
        n = str(i);
        if (len(n) < unkNums) {
            padding = int((unkNums - len(n)));
            n = n.zfill((padding + 1));
            my_list.append(n);
        } else {
            my_list.append(n);
        }
    }
    return my_list;
}

"""
    Get value from a model or dict or list with field
    Field must be a string or number value

    usage:

        >>> model_value_with_field({"key1": "value1", "key2": "value2"}, "key1", "default")
        "value1"
        >>> model_value_with_field({"key1": "value1", "key2": "value2"}, "key3", "default")
        "default"
        >>> model_value_with_field(["1", "2", "3"], 2, "default")
        "3"
        >>> model_value_with_field(["1", "2", "3"], 4, "default")
        "default"

    :param model: origin model or dict or list
    :param field: which value want to get
    :param null: default value if field not in model
    """
def get_value_with_field(model: Any, field: Any, null: Any = None) -> object {
    if not model {
        return null;
    }
    if isinstance(model, `dict) {
        return model.get(field, null);
    }
    if isinstance(model, `list) {
        try {
            index = int(field);
            if (len(model) <= index) {
                return null;
            }
            return `list(model)[index];
        } except TypeError {
            return null;
        }
    }
    if hasattr(model, field) {
        return getattr(model, field);
    }
    return null;
}
